contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // We take the depositor, recipient, and amount as inputs. The test contract itself must hold
    // enough mAsset to approve/transfer; the checker will provide a fresh c and arbitrary parameters.
    // This test focuses on the supplyTokenTo behavior: after supplying, the recipient's balanceOfToken
    // (which uses imBalances * exchangeRate / 1e18) should be >= the mAssetAmount passed in converted
    // via the exchangeRate at the time of the call. We also assert that imBalances for the recipient did
    // not decrease (observable via balanceOfToken monotonicity with same exchangeRate).

    // Note: we cannot call mAsset.transferFrom from this contract as msg.sender of c.supplyTokenTo will be
    // this contract when c tries to pull tokens; however the specification of the environment allows any
    // external token behavior. The checker will reason about calls symbolically. We only invoke c.supplyTokenTo
    // and then read public views to assert the general invariant.

    function run(address recipient, uint256 mAssetAmount) public payable {
        require(recipient != address(0));

        // Read exchange rate before the call
        uint256 rateBefore = c.savings().exchangeRate();

        // Read recipient's underlying balance before (in mAssets) via balanceOfToken view
        uint256 beforeUnderlying = c.balanceOfToken(recipient);

        // Call supplyTokenTo; follow constraints: top-level external call that mutates c's state
        bool reverted;
        try c.supplyTokenTo(mAssetAmount, recipient) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read exchange rate and balance after
        uint256 rateAfter = c.savings().exchangeRate();
        uint256 afterUnderlying = c.balanceOfToken(recipient);

        // If the call reverted, then the state should be unchanged: afterUnderlying equals beforeUnderlying
        // If the call succeeded, then the recipient's underlying (afterUnderlying) should be >=
        // (mAssetAmount * rateBefore) / 1e18 added to beforeUnderlying. We use rateBefore to avoid relying on
        // post-call exchange rate changes increasing apparent balance (exchangeRate may change externally).
        // Also ensure that imBalances did not decrease: since balanceOfToken is proportional to imBalances via rate,
        // we assert afterUnderlying >= beforeUnderlying when the call succeeded.

        assert(
            (reverted && afterUnderlying == beforeUnderlying) ||
            (!reverted && afterUnderlying >= beforeUnderlying + (mAssetAmount * rateBefore) / 1e18 && afterUnderlying >= beforeUnderlying)
        );
    }

    // receive to accept ETH if needed by underlying tokens during calls
    receive() external payable {}
}

