contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function: supplyTokenTo should increase balanceOfToken for `to`
    // params: mAssetAmount (amount of mAsset to transfer), to (recipient address)
    function run(uint256 mAssetAmount, address to) public payable {
        require(to != address(0), "to cannot be zero");
        // precondition: ensure this contract has enough mAsset to transfer to c
        // We observe mAsset via c.depositToken() which returns address of underlying mAsset
        IERC20 m = IERC20(c.depositToken());
        // We cannot mint tokens, but we can only proceed when this test contract already has enough balance.
        // If not, the call will revert in c.supplyTokenTo due to safeTransferFrom; we allow that and assert accordingly.

        // Read before value: recipient's underlying mAssets according to c.balanceOfToken
        uint256 before = c.balanceOfToken(to);

        bool reverted;
        try c.supplyTokenTo(mAssetAmount, to) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 after = c.balanceOfToken(to);

        // General rule: if supplyTokenTo did not revert then after >= before,
        // and the nominal increase in underlying mAssets reported should be consistent with deposited mAssetAmount
        // converted through savings.exchangeRate: expectedIncrease = (mAssetAmount * exchangeRate) / 1e18
        uint256 exchangeRate = c.savings().exchangeRate();
        uint256 expectedIncrease = (mAssetAmount * exchangeRate) / 1e18;

        // If the call reverted, no state change is required. If it did not revert, then after >= before and
        // the increase should be at least expectedIncrease (credits rounding may make equality not exact on reverse mapping).
        assert(
            reverted || (after >= before && (after - before) >= expectedIncrease)
        );
    }

    // minimal interface types used (declared locally to satisfy compiler usage)
    receive() external payable {}
}

