contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We take as inputs: mAssetAmount to supply and the beneficiary address `to`.
    // The test will call c.supplyTokenTo and then assert that the beneficiary's
    // credit balance (observed indirectly through c.balanceOfToken and exchangeRate)
    // does not decrease compared to before the call. This enforces that supply
    // mints (or keeps) credits for the `to` account and never reduces their share.
    function run(uint256 mAssetAmount, address to) public payable {
        require(to != address(0));
        // Observe exchange rate before
        uint256 rateBefore = c.savings().exchangeRate();
        // Observe underlying-derived value for `to` before
        uint256 balBefore = c.balanceOfToken(to);

        // Perform the state-changing call: supplyTokenTo must be a top-level call
        // The caller of c.supplyTokenTo is this contract (msg.sender for c will be this contract).
        // The call may revert; capture that.
        bool reverted;
        try c.supplyTokenTo(mAssetAmount, to) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // After call, observe rate and balance
        uint256 rateAfter = c.savings().exchangeRate();
        uint256 balAfter = c.balanceOfToken(to);

        // General rule (single assert): If the call did not revert, then the beneficiary's
        // observed balanceOfToken must be >= previous balanceOfToken (supply must not decrease
        // the beneficiary's underlying-equivalent balance). If the call reverted, we cannot
        // make claims about balances, so require no further condition. This is a general
        // behavioral invariant: successful supply cannot reduce the beneficiary's balance.
        assert(reverted || balAfter >= balBefore);
    }

    // Minimal receive to accept any refunds/transfers if needed
    receive() external payable {}
}

