contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test entry. We take mAssetAmount and recipient address as inputs.
    function run(uint256 mAssetAmount, address to) public payable {
        require(to != address(0), "recipient nonzero");

        // Caller of c (msg.sender for c calls) will be this contract.
        // We must ensure this contract has approved the mAsset to c and has balance; however
        // we can only interact through c's public surface. The contract C constructor already
        // approved savings for max and set mAsset. We cannot mint tokens here; instead we
        // rely on the check being a general relation between imBalances change and creditsIssued
        // when supplyTokenTo does not revert. Therefore we attempt the call and record whether it reverted,
        // and if it succeeded we compare the observed imBalances delta to the creditsReported by
        // comparing pre/post via c.creditBalances (not present) — but creditBalances is in ISavingsContractV2
        // not on C. C exposes imBalances via auto getter imBalances(address) which is public.

        // Read balance before
        uint256 before = c.imBalances(to);

        // Try to call supplyTokenTo; catch revert
        bool reverted;
        try c.supplyTokenTo(mAssetAmount, to) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 after = c.imBalances(to);

        // General rule: if supplyTokenTo succeeded (did not revert) then imBalances[to] must have increased
        // (or stayed same if creditsIssued was zero) by a non-negative amount equal to (after - before).
        // We assert that whenever the call did not revert, after >= before. This captures that supplyTokenTo
        // cannot decrease the beneficiary's imBalances when it succeeds.

        assert(reverted || after >= before);
    }

    receive() external payable {}
}

