contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public test entry
    function run(uint256 mAssetAmount) public payable {
        // no precondition on mAssetAmount; allow 0 as well

        // Read imBalances before attempting redeem
        uint256 before = c.imBalances(address(this));

        // Attempt to call redeemToken and record whether it reverted
        bool reverted;
        uint256 returned;
        try c.redeemToken(mAssetAmount) returns (uint256 r) {
            reverted = false;
            returned = r;
        } catch {
            reverted = true;
            returned = 0;
        }

        // Read imBalances after the call
        uint256 after = c.imBalances(address(this));

        // General rule: if redeemToken succeeded (did not revert) then imBalances of this must not have increased
        // i.e., after <= before. This asserts that a successful redeem reduces or preserves credits, not increases them.
        assert(reverted || after <= before);
    }

    receive() external payable {}
}

