contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We test interplay of supplyTokenTo and redeemToken: after supplying mAssetAmount to `to`,
    // the observable balanceOfToken(to) must reflect at least the supplied underlying when
    // converted back using the savings.exchangeRate seen before the supply. Then, if msg.sender
    // later redeems via redeemToken, the actual mAssets returned cannot exceed the requested
    // amount and the caller's observable balanceOfToken decreases (or stays <= previous).
    // We perform a single supplyTokenTo followed by an attempted redeemToken by the caller.
    function run(uint256 mAssetAmount, address to, uint256 redeemRequest) public payable {
        require(mAssetAmount > 0 && to != address(0));

        // Observe exchange rate and balances before any state change
        ISavingsContractV2 savings = c.savings();
        uint256 exchangeRateBefore = savings.exchangeRate();
        uint256 beforeBalanceOfTo = c.balanceOfToken(to);
        uint256 beforeBalanceOfCaller = c.balanceOfToken(address(this));

        // Transfer: call supplyTokenTo. This will attempt to transfer mAsset from msg.sender (this test)
        // so the test contract must have approved and hold tokens in the harness environment; if it reverts
        // the catch below records that.
        bool supplyReverted;
        try c.supplyTokenTo(mAssetAmount, to) {
            supplyReverted = false;
        } catch {
            supplyReverted = true;
        }

        // After supply (if not reverted) observe balanceOfToken(to)
        uint256 afterBalanceOfTo = c.balanceOfToken(to);

        // We now attempt redeemToken by this contract (address(this)) with redeemRequest
        bool redeemReverted;
        uint256 mAssetsReturned = 0;
        try c.redeemToken(redeemRequest) returns (uint256 returned) {
            redeemReverted = false;
            mAssetsReturned = returned;
        } catch {
            redeemReverted = true;
        }

        uint256 afterBalanceOfCaller = c.balanceOfToken(address(this));

        // General assertions to capture invariants:
        // 1) If supply succeeded, the increase in balanceOfToken(to) when converted to underlying
        //    using the exchangeRateBefore should be at least mAssetAmount (i.e., credits issued represent >= supplied underlying at that rate).
        //    We rewrite: deltaCredits = after - before; underlyingEquivalent = (deltaCredits * exchangeRateBefore) / 1e18;
        //    require underlyingEquivalent >= mAssetAmount.
        // 2) If redeem succeeded, the returned mAssets cannot exceed the requested redeemRequest.
        // 3) If redeem succeeded, caller's observable balanceOfToken should be <= before (it should not increase).
        // Note: if supply or redeem reverted, we don't enforce the corresponding numeric relation.

        // compute delta credits safely without underflow (after >= before if supply succeeded by design)
        uint256 deltaCreditsTo = afterBalanceOfTo >= beforeBalanceOfTo ? afterBalanceOfTo - beforeBalanceOfTo : 0;
        uint256 underlyingEquivalent;
        // avoid multiplication overflow: use unchecked with 256-bit is fine for these symbolic checks in this context
        underlyingEquivalent = (deltaCreditsTo * exchangeRateBefore) / 1e18;

        assert(
            (
                supplyReverted || underlyingEquivalent >= mAssetAmount
            ) && (
                redeemReverted || mAssetsReturned <= redeemRequest
            ) && (
                redeemReverted || afterBalanceOfCaller <= beforeBalanceOfCaller
            )
        );
    }

    receive() external payable {}
}

