    // We cannot manipulate external token approvals here; the checker will reason about all inputs.
    function run(uint256 fromAmount, address to, uint256 redeemAmount) public payable {
        require(to != address(0));

        // Observe C's mAsset token address and c's balance before any mutating calls
        address mAssetAddr = c.depositToken();
        uint256 cBalanceBefore = address(c).balance;

        // read balanceOfToken for two addresses before
        uint256 balanceToBefore = c.balanceOfToken(to);
        uint256 balanceThisBefore = c.balanceOfToken(address(this));

        // Attempt supplyTokenTo: may revert if transferFrom fails; capture revert flag
        bool supplyReverted;
        try c.supplyTokenTo(fromAmount, to) {
            supplyReverted = false;
        } catch {
            supplyReverted = true;
        }

        // After supply attempt, observe balanceOfToken again
        uint256 balanceToAfter = c.balanceOfToken(to);
        uint256 balanceThisAfter = c.balanceOfToken(address(this));
        uint256 cBalanceMid = address(c).balance;

        // Attempt redeemToken by this contract (msg.sender is this test contract)
        bool redeemReverted;
        uint256 redeemedActual = 0;
        try c.redeemToken(redeemAmount) returns (uint256 mAssetsActual) {
            redeemReverted = false;
            redeemedActual = mAssetsActual;
