                (redeemReverted && balanceToAfter == balanceToBefore)
            )
            &&
            (
                // c's ether balance only changes if payable calls happened; since C has no payable mutating functions used,
                // require that c's native balance never decreased (safety: no unexpected Ether drain)
                cBalanceAfter >= cBalanceBefore
            )
        );
    }

    receive() external payable {}
}

