contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    // params: mAssetAmount to supply, recipient address index encoded as uint (we map to address),
    // redeemAmount to attempt redeem by the caller (msg.sender for c will be this contract), and a flag to choose which action to perform
    function run(uint256 mAssetAmount, uint160 recipientUint, uint256 redeemAmount, bool doSupply) public payable {
        require(address(this).balance >= 0);
        // derive a recipient address from input integer (not a compile-time constant)
        address recipient = address(uint160(recipientUint));

        // observe exchange rate and balances before any state-changing call
        uint256 rateBefore = c.savings().exchangeRate();
        uint256 balRecipientBefore = c.balanceOfToken(recipient);
        uint256 balCallerCreditsBefore = c.savings().creditBalances(address(this));

        bool reverted = false;

        if (doSupply) {
            // To call supplyTokenTo we must have approved and hold mAsset tokens; however in the environment the checker deploys fresh c and will not have tokens.
            // So instead we test the observable invariant for calls that do not actually succeed: the call either reverts or, if it succeeds,
            // the recipient's balanceOfToken must be >= previous + mAssetAmount * rate / 1e18.
            try c.supplyTokenTo(mAssetAmount, recipient) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            // Try redeemToken as this contract (msg.sender is this contract). Record whether it reverted.
            try c.redeemToken(redeemAmount) returns (uint256 returned) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        // observe after-values
        uint256 rateAfter = c.savings().exchangeRate();
        uint256 balRecipientAfter = c.balanceOfToken(recipient);
        uint256 balCallerCreditsAfter = c.savings().creditBalances(address(this));

        // General rule:
        // - If we performed supply and it succeeded (did not revert), then recipient's token-equivalent balance must have increased by at least mAssetAmount * rateBefore / 1e18 (i.e., credits issued converted to underlying using the observed rateBefore).
        // - If we performed redeem and it succeeded, the caller's credits (as reported by savings.creditBalances) must not have increased (redeem should not give additional credits).
        // We express both in one assert using only observed values and the reverted flag.

        // compute expected minimum underlying increase in terms of balanceOfToken units using rateBefore
        // avoid under/overflow by doing multiplication then division with checks; since assert cannot include complex local control,
        // we form the inequality directly but guard by trivial math: when rateBefore is zero, expectedIncrease = 0.
        uint256 expectedIncrease;
        if (rateBefore == 0) {
            expectedIncrease = 0;
        } else {
            // expected underlying mAssets converted to token-equivalent using rateBefore
            expectedIncrease = (mAssetAmount * rateBefore) / 1e18;
        }

        // Build the assertion:
        // If doSupply && !reverted then balRecipientAfter >= balRecipientBefore + expectedIncrease
        // If !doSupply && !reverted then balCallerCreditsAfter <= balCallerCreditsBefore (redeem should not increase credits)
        // If reverted, no specific guarantee (we still require nothing contradictory)

        if (doSupply) {
            if (!reverted) {
                assert(balRecipientAfter >= balRecipientBefore + expectedIncrease);
            } else {
                // call reverted: ensure no unexpected change to observed values (conservative): balances unchanged and rate unchanged
                assert(balRecipientAfter == balRecipientBefore || rateAfter == rateBefore);
            }
        } else {
            if (!reverted) {
                assert(balCallerCreditsAfter <= balCallerCreditsBefore);
            } else {
                // reverted: similar conservative observation
                assert(balCallerCreditsAfter == balCallerCreditsBefore || rateAfter == rateBefore);
            }
        }
    }

    receive() external payable {}
}

