    // - redeemAmount: amount to attempt to redeem by this contract
    // - doSupply: if true call supplyTokenTo, otherwise call redeemToken
    function run(uint256 mAssetAmount, uint160 recipientUint, uint256 redeemAmount, bool doSupply) public payable {
        require(true);

        address recipient = address(uint160(recipientUint));

        // observe before-values
        uint256 rateBefore = c.savings().exchangeRate();
        uint256 balRecipientBefore = c.balanceOfToken(recipient);
        uint256 balCallerCreditsBefore = c.savings().creditBalances(address(this));

        // We must perform any state-changing call as a top-level statement.
        // Record whether it reverted using try/catch in a top-level statement as well.
        bool reverted;
        uint256 returnedRedeem;

        if (doSupply) {
            try c.supplyTokenTo(mAssetAmount, recipient) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            try c.redeemToken(redeemAmount) returns (uint256 r) {
                reverted = false;
                returnedRedeem = r;
            } catch {
                reverted = true;
            }
        }

        // observe after-values
        uint256 rateAfter = c.savings().exchangeRate();
        uint256 balRecipientAfter = c.balanceOfToken(recipient);
        uint256 balCallerCreditsAfter = c.savings().creditBalances(address(this));

        // compute expected increase in token-equivalent units using rateBefore (if rateBefore==0 expect zero)
        uint256 expectedIncrease = 0;
        if (rateBefore != 0) {
            expectedIncrease = (mAssetAmount * rateBefore) / 1e18;
        }

        // Single assert capturing both cases:
        // - If we did supply and it did not revert: recipient's balanceOfToken increased by at least expectedIncrease.
        // - If we did redeem and it did not revert: caller's credits did not increase.
        // - If the call reverted, we impose no strict increase requirement (allowing reverts), but still require that if a revert happened then neither observed invariant-violating increase occurred.
        // The formula below encodes: (doSupply && !reverted) => balRecipientAfter >= balRecipientBefore + expectedIncrease
        //                          ( !doSupply && !reverted) => balCallerCreditsAfter <= balCallerCreditsBefore
        // For reverted cases, the RHS of the implications is true (we allow no-op), so combine using logical implications implemented with booleans.

        assert((!doSupply && reverted) || (doSupply && reverted) ||
               (doSupply && !reverted && balRecipientAfter >= balRecipientBefore + expectedIncrease) ||
               (!doSupply && !reverted && balCallerCreditsAfter <= balCallerCreditsBefore));
    }

    receive() external payable {}
}

