        // Precondition: this contract must have enough mAsset balance to call supplyTokenTo.
        // We can only interact via c; assume caller funded this test contract externally with mAsset tokens
        // The test will attempt supplyTokenTo and then attempt redeemToken; both may revert.

        // Read balances and imBalances before operations
        uint256 beforeImTo = c.imBalances(to);
        uint256 beforeImThis = c.imBalances(address(this));
        uint256 beforeMAssetBalC = c.mAsset().balanceOf(address(c));
        uint256 beforeMAssetBalThis = c.mAsset().balanceOf(address(this));

        // Attempt to supply: record whether it reverts; on success imBalances[to] should increase by creditsIssued
        bool supplyReverted;
        try c.supplyTokenTo(mAssetAmount, to) {
            supplyReverted = false;
        } catch {
            supplyReverted = true;
        }

        // Read after supply
        uint256 afterImTo = c.imBalances(to);
        uint256 afterImThis = c.imBalances(address(this));
        uint256 afterMAssetBalC = c.mAsset().balanceOf(address(c));
        uint256 afterMAssetBalThis = c.mAsset().balanceOf(address(this));

        // Attempt to redeem as msg.sender = this contract (redeemToken uses msg.sender). Record revert.
        bool redeemReverted;
        uint256 redeemedActual = 0;
        try c.redeemToken(redeemAmount) returns (uint256 ret) {
            redeemReverted = false;
            redeemedActual = ret;
        } catch {
            redeemReverted = true;
        }

        uint256 finalImThis = c.imBalances(address(this));
        uint256 finalMAssetBalC = c.mAsset().balanceOf(address(c));
        uint256 finalMAssetBalThis = c.mAsset().balanceOf(address(this));

        // General rule asserted:
        // 1) If supplyTokenTo did not revert, then imBalances[to] did not decrease and increased by some nonzero (or zero) amount equal to after-before.
        // 2) The contract's mAsset balance after supply is >= before (since supply pulls tokens into c via transferFrom) unless supply reverted.
        // 3) If redeemToken succeeded, then the returned redeemedActual equals the increase in this contract's mAsset balance, and imBalances[this] decreased by exactly the credits burned (observed as before-after on imBalances).

