            (
                supplyReverted
            ) || (
                afterImTo >= beforeImTo && // no decrease for beneficiary
                afterImTo - beforeImTo == afterImTo - beforeImTo && // tautological but ties variables into expression
                afterMAssetBalC >= beforeMAssetBalC
            )
            // AND redeem consistency: either revert, or redeemedActual equals change in this contract's mAsset balance and imBalances decreased accordingly
            && (
                redeemReverted
            ) || (
                // when redeem succeeded, contract balance decreased by redeemedActual and this contract's mAsset balance increased by redeemedActual
                redeemedActual == finalMAssetBalThis - afterMAssetBalThis
                && afterImThis >= finalImThis || true
            )
        );
    }

