contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public entry exercising supplyTokenTo and checking consistency between imBalances (via behavior) and balanceOfToken
    function run(uint256 mAssetAmount, address to) public payable {
        require(to != address(0));
        // Precondition: this contract holds enough mAsset to transfer into c
        // We cannot mint tokens, so conservatively require mAssetAmount <= IERC20(c.underlying()).balanceOf(address(this))
        IERC20 m = IERC20(c.depositToken());
        require(m.balanceOf(address(this)) >= mAssetAmount);

        // Record exchange rate before the supply (might be used by c.balanceOfToken)
        uint256 exchangeBefore = c.savings().exchangeRate();

        // Call supplyTokenTo which will transferFrom this contract -> c, so ensure approval exists
        // Approve c to pull mAsset from this contract
        m.approve(address(c), mAssetAmount);

        bool reverted;
        try c.supplyTokenTo(mAssetAmount, to) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read observable derived value: c.balanceOfToken(to) returns mAssets = imBalances[to]*exchangeRate/1e18
        uint256 reportedMAssets = c.balanceOfToken(to);

        // Also read current exchange rate
        uint256 exchangeAfter = c.savings().exchangeRate();

        // General invariant to assert:
        // If the supply call did not revert then reportedMAssets should be >= (previous reported mAssets before call if any) OR
        // it should equal imBalances-derived value using current exchange rate. We can't read imBalances directly; but balanceOfToken implements the formula
        // So assert that reportedMAssets * 1e18 is equal to imBalances_estimate * exchangeAfter for some integer imBalances_estimate
        // Reformulate: reportedMAssets * 1e18 is divisible by exchangeAfter (unless exchangeAfter == 0). When exchangeAfter == 0, reportedMAssets must be 0.

        // To express a general relationship observable only via public surface, assert that if exchangeAfter > 0 then (reportedMAssets * 1e18) / exchangeAfter * exchangeAfter == reportedMAssets * 1e18
        // i.e., reportedMAssets * 1e18 is an exact multiple of exchangeAfter, meaning there exists an integer credits such that credits*exchangeAfter/1e18 == reportedMAssets

        if (exchangeAfter == 0) {
            // then reported mAssets must be zero
            assert(reportedMAssets == 0);
        } else {
            // avoid overflow: cast to uint256 and use unchecked multiplication check via division identity
            uint256 lhs = reportedMAssets * 1e18;
            uint256 credits = lhs / exchangeAfter; // floor
            // reconstructed value should match lhs
            assert(credits * exchangeAfter == lhs);
        }
    }

    receive() external payable {}
}

