        try c.supplyTokenTo(mAssetAmount, to) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // observe after
        uint256 afterBal = c.balanceOfToken(to);

        // General rule: if reverted then balance unchanged; if succeeded then balance did not decrease
        assert((reverted && afterBal == beforeBal) || (!reverted && afterBal >= beforeBal));
    }

    receive() external payable {}
}

